module NecklaceSplit(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input [3:0] k_i,\n    input [3:0] n_i,\n    input [15:0] bead_weights [0:15],\n    output reg done,\n    output reg [0:0] result\n);\n    // State definitions\n    localparam [2:0]\n        IDLE      = 3'd0,\n        CALC_SUM  = 3'd1,\n        CHECK_DIV = 3'd2,\n        TRY_START = 3'd3,\n        DONE_ST   = 3'd4;\n\n    reg [2:0] state, next_state;\n    reg [19:0] total_sum;\n    reg [19:0] target;\n    reg [3:0] current_start;\n    reg [7:0] cycle_count;\n    reg start_success;\n\n    // Calculate total sum combinatorially\n    reg [19:0] next_total_sum;\n    integer sum_idx;\n    always @(*) begin\n        next_total_sum = 20'd0;\n        for (sum_idx = 0; sum_idx < n_i; sum_idx = sum_idx + 1) begin\n            next_total_sum = next_total_sum + bead_weights[sum_idx];\n        end\n    end\n\n    // Check if current_start is a valid start position\n    always @(*) begin\n        reg [19:0] c_sum;\n        reg [3:0] c_segment;\n        reg [3:0] c_pos;\n        integer i;\n        c_sum = 20'd0;\n        c_segment = 4'd0;\n        c_pos = current_start;\n        for (i = 0; i < n_i; i = i + 1) begin\n            c_sum = c_sum + bead_weights[c_pos];\n            if (c_sum == target) begin\n                c_segment = c_segment + 4'd1;\n                c_sum = 20'd0;\n                if (c_segment == k_i) begin\n                    break;\n                end\n            end else if (c_sum > target) begin\n                break;\n            end\n            c_pos = (c_pos + 4'd1) % n_i;\n        end\n        start_success = (c_segment == k_i);\n    end\n\n    // FSM and sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            total_sum <= 20'd0;\n            target <= 20'd0;\n            current_start <= 4'd0;\n            cycle_count <= 8'd0;\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            done <= 1'b0;\n\n            case (state)\n                IDLE: begin\n                    result <= 1'b0;\n                    if (start) begin\n                        state <= CALC_SUM;\n                        cycle_count <= 8'd1;\n                    end\n                end\n\n                CALC_SUM: begin\n                    total_sum <= next_total_sum;\n                    state <= CHECK_DIV;\n                end\n\n                CHECK_DIV: begin\n                    if (total_sum % k_i != 20'd0) begin\n                        result <= 1'b0;\n                        state <= DONE_ST;\n                    end else begin\n                        target <= total_sum / k_i;\n                        current_start <= 4'd0;\n                        state <= TRY_START;\n                    end\n                end\n\n                TRY_START: begin\n                    if (start_success) begin\n                        result <= 1'b1;\n                        state <= DONE_ST;\n                    end else if (current_start < (n_i - 4'd1)) begin\n                        current_start <= current_start + 4'd1;\n                    end else begin\n                        result <= 1'b0;\n                        state <= DONE_ST;\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n\n            // Timeout handling\n            if (cycle_count >= 8'd200) begin\n                state <= DONE_ST;\n                result <= 1'b0;\n            end\n        end\n    end\n\nendmodule